import handler from './.open-next/worker.js';
// @ts-ignore Generated JavaScript has no declaration file.
import { runWithCloudflareRequestContext } from './.open-next/cloudflare/init.js';
import type { ExportedHandler } from '@cloudflare/workers-types';
import { recoverWorkerPdfJobs } from '@/lib/pdf/worker-jobs';
import { expireWorkerEmails, processWorkerEmails } from '@/lib/email/worker-queue';
import { cleanupWorkerObjects } from '@/lib/server/worker-cleanup';
import { cleanupWorkerCertificateJobs, processWorkerCertificateJobs } from '@/lib/agent/worker-jobs';
import { logAgentError } from '@/lib/agent/log';

export default {
  fetch: handler.fetch,
  async scheduled(_event, env, ctx) {
    const request = new Request(`${process.env.NEXTAUTH_URL || 'https://bamboobot.tk.sg'}/internal/job-recovery`);
    await runWithCloudflareRequestContext(request, env, ctx, async () => {
      // Independent failures must not starve unrelated durable queues. Existing
      // PDF/email budgets leave headroom for a bounded agent preflight slice.
      const operations = [
        () => expireWorkerEmails(),
        () => processWorkerEmails(undefined, 5_000),
        () => recoverWorkerPdfJobs(),
        () => processWorkerCertificateJobs(),
        () => cleanupWorkerCertificateJobs(),
        () => cleanupWorkerObjects(),
      ];
      for (const operation of operations) {
        try { await operation(); }
        catch (error) { logAgentError('Scheduled operation failed; continuing other queues', error); }
      }
      return new Response(null, { status: 204 });
    });
  },
} satisfies ExportedHandler<CloudflareEnv>;

// Preserve the adapter's exports for any later cache configuration.
// @ts-ignore Generated JavaScript has no declaration file.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
